 <script>(function(){var list=document.getElementById('newsletterArtistList'),add=document.getElementById('newsletterAddArtist'),template=document.getElementById('newsletterArtistTemplate');if(!list||!add||!template)return;function renumber(){var cards=list.querySelectorAll('.newsletter-artist');for(var i=0;i<cards.length;i++)cards[i].querySelector('.newsletter-artist-role').textContent=i===0?'Artista principal':'Artista secundario '+i;}add.addEventListener('click',function(){if(list.querySelectorAll('.newsletter-artist').length>=8){alert('Máximo 8 artistas.');return;}list.appendChild(template.content.cloneNode(true));renumber();});list.addEventListener('click',function(event){var button=event.target.closest('.newsletter-remove-artist');if(!button)return;button.closest('.newsletter-artist').remove();if(!list.querySelector('.newsletter-artist'))add.click();renumber();});renumber();})();</script>
